export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

export interface Quote {
  premium: number;
}

function basePremiumOf(_item: Item): number {
  return SWORD_BASE_PREMIUM;
}

function policyBasePremium(items: Item[]): number {
  return items.reduce((total, item) => total + basePremiumOf(item), 0);
}

export function quote(
  _customer: Customer,
  items: Item[],
  _previousContracts: number,
): Quote {
  const base = policyBasePremium(items);
  return { premium: base + base * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE };
}

