import { policyWideAdjustment, type Customer } from "./customer-modifiers.js";
import { payoutCap } from "./policy.js";
import { basePremiumOf, type Item } from "./price-list.js";
import { riskSurchargeFor } from "./risk.js";

const PROCESSING_FEE = 5;

export interface Quote {
  premium: number;
  cap: number;
}

export type { Customer, Item };

function roundedInMHPCOsFavour(premium: number): number {
  return Math.ceil(premium);
}

function policyBasePremium(items: Item[]): number {
  return items.reduce((total, item) => total + basePremiumOf(item), 0);
}

function itemSurcharges(items: Item[]): number {
  return items.reduce((total, item) => total + riskSurchargeFor(item), 0);
}

export function quote(
  customer: Customer,
  items: Item[],
  _previousContracts: number,
): Quote {
  const base = policyBasePremium(items);
  const premium =
    base + itemSurcharges(items) + policyWideAdjustment(customer, base) + PROCESSING_FEE;
  return {
    premium: roundedInMHPCOsFavour(premium),
    cap: payoutCap(items),
  };
}

